import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.tree.SessionDocument;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.jupiter.api.Test;

final class MemoryHostStoreFaultInjectionTest {
    private static final Instant NOW = Instant.parse("2026-09-04T00:00:00Z");

    @Test
    void queuedPromptProjectionFailureLeavesJournalQueueAndWatermarksWhollyBefore() {
        var mapper = new FailNextObjectMapper();
        var store = new MemoryHostStore(mapper);
        store.create("session-1", new ModelRef("faux", "model"), "workspace", NOW);
        store.reserve("session-1", "active-command", "active-hash", "active-run", 0);
        SessionDocument running = store.update("session-1", 0, document -> document.startRun(
                new SessionDocument.RunStart(
                        "active-run", "turn-1", "attempt-1", "result-entry-1", normalMessage(),
                        "operation-start-1", "attempt-record-1", NOW)));
        FollowUpQueue beforeQueue = store.queue("session-1");
        HostStore.Snapshot beforeSnapshot = store.snapshot("session-1");
        List<HostStore.DurableEvent> beforeEvents = store.replay("session-1", 0);

        mapper.failNext();
        assertThrows(IllegalStateException.class,
                () -> store.acceptPrompt("session-1", "command-1", "hash-1", "queue-1",
                        running.revision(), "desktop", List.of("prompt"), List.of()));

        assertAll("a failed projection must not expose any subset of the proposed Host commit",
                () -> assertEquals(running, store.load("session-1").orElseThrow()),
                () -> assertEquals(beforeQueue, store.queue("session-1")),
                () -> assertTrue(store.command("session-1", "command-1", "hash-1").isEmpty()),
                () -> assertEquals(beforeSnapshot.revision(), store.snapshot("session-1").revision()),
                () -> assertEquals(beforeSnapshot.baseEventSeq(), store.snapshot("session-1").baseEventSeq()),
                () -> assertArrayEquals(beforeSnapshot.payload(), store.snapshot("session-1").payload()),
                () -> assertEquals(beforeEvents.size(), store.replay("session-1", 0).size()),
                () -> assertEquals(2, store.reserve(
                        "session-1", "command-2", "hash-2", "run-2", running.revision()).acceptedSeq()));
    }

    @Test
    void terminalProjectionFailureLeavesCanonicalJournalAndWatermarksWhollyBefore() {
        var mapper = new FailNextObjectMapper();
        var store = new MemoryHostStore(mapper);
        store.create("session-1", new ModelRef("faux", "model"), "workspace", NOW);
        store.reserve("session-1", "command-1", "hash-1", "run-1", 0);
        SessionDocument running = store.update("session-1", 0, document -> document.startRun(
                new SessionDocument.RunStart(
                        "run-1", "turn-1", "attempt-1", "result-entry-1", normalMessage(),
                        "operation-start-1", "attempt-record-1", NOW)));
        FollowUpQueue beforeQueue = store.queue("session-1");
        HostStore.Snapshot beforeSnapshot = store.snapshot("session-1");
        List<HostStore.DurableEvent> beforeEvents = store.replay("session-1", 0);

        mapper.failNext();
        assertThrows(IllegalStateException.class, () -> store.update("session-1", running.revision(),
                document -> document.finishRun(new SessionDocument.RunCompletion(
                        "run-1", 0, "turn-1", 0, "attempt-1", 0,
                        List.of(), Usage.ZERO, CanonicalSessionState.RunOutcome.FAILED,
                        "usage-record-1", "operation-finish-1", NOW.plusSeconds(1)))));

        HostStore.CommandRecord command = store.command("session-1", "command-1", "hash-1").orElseThrow();
        assertAll(
                () -> assertEquals(running, store.load("session-1").orElseThrow()),
                () -> assertEquals(HostStore.Status.RESERVED, command.status()),
                () -> assertTrue(command.commit().isEmpty()),
                () -> assertEquals(beforeQueue, store.queue("session-1")),
                () -> assertEquals(beforeSnapshot.revision(), store.snapshot("session-1").revision()),
                () -> assertEquals(beforeSnapshot.baseEventSeq(), store.snapshot("session-1").baseEventSeq()),
                () -> assertArrayEquals(beforeSnapshot.payload(), store.snapshot("session-1").payload()),
                () -> assertEquals(beforeEvents.size(), store.replay("session-1", 0).size()));
    }

    private static Message normalMessage() {
        return new Message("message-1", Message.Role.USER,
                List.of(new io.github.diodeme.ji.ai.Content.Text("prompt")), NOW);
    }

    private static final class FailNextObjectMapper extends ObjectMapper {
        private static final long serialVersionUID = 1L;
        private final AtomicBoolean fail = new AtomicBoolean();

        void failNext() {
            fail.set(true);
        }

        @Override
        public byte[] writeValueAsBytes(Object value) throws JsonProcessingException {
            if (fail.compareAndSet(true, false)) {
                throw JsonMappingException.fromUnexpectedIOE(
                        new java.io.IOException("injected projection serialization failure"));
            }
            return super.writeValueAsBytes(value);
        }
    }
}
